function renderAuditPage({DATA,MODEL,$,fmt,esc,unit,factBtn,sheetBtn,heading}){
 $('page-audit').innerHTML=heading('ПРОЕКТНЫЕ ЛИСТЫ','Сверка модели с проектом','Здесь собраны расхождения в размерах и варианты, для которых ещё нужны рабочие привязки.','По трём альбомам')+
 `<div class="card"><h3>Решения по пункту 24</h3>
 <details open><summary>Шесть групп рабочих узлов</summary>
 <div class="table-wrap"><table><thead><tr><th>Узел</th><th>Выбор для модели</th><th>Другой вариант</th><th>Что проверить до работ</th></tr></thead><tbody>
 ${MODEL.coordination_decisions.map(row=>`<tr><th>${esc(row.title)}<small class="block-note">${row.sheets.map(([album,page])=>sheetBtn(album,page)).join(' ')}</small></th><td>${esc(row.adopted)}</td><td>${esc(row.alternative)}</td><td>${esc(row.pending)}</td></tr>`).join('')}
 </tbody></table></div></details></div>
 <div class="card"><h3>Какие размеры можно проверить</h3><div class="table-wrap"><table><thead><tr><th>Модель</th><th>Сверено по листам</th><th>Что требует уточнения</th></tr></thead><tbody>
 <tr><td>Фундамент и арматура</td><td>Отметки, четыре сечения, восемь позиций арматуры и нахлёст. Прямой край террасы принят 18 ноября.</td><td>Зона верхнего шага 150 мм, рабочие стыки и новые ступени Крм 2.</td></tr>
 <tr><td>Закладные и трубы</td><td>Семь привязок в плане ВК-1 и проходы через плиту по КЖ-2.</td><td>Глубины и трасса до септика. Для воды встречаются Ø63, 65 и Ø32.</td></tr>
 <tr><td>Этажи и кладка</td><td>Планы обоих этажей, проёмы и оконные блоки АР-3…7, АР-16/17.</td><td>Верх стен мансарды, рабочая перевязка и монтажные узлы блоков. Марки и открывание дверей 7/8 приняты по АР-5/6.</td></tr>
 <tr><td>Лестница и Пм 1</td><td>Ширина маршей, проступи, отметка площадки и проём по КЖ-7/15.</td><td>Расхождения цепочек 10 и 40 мм и объём Пм 1 в ведомости.</td></tr>
 <tr><td>Кровля и каркас</td><td>Скаты АР-8, сечения древесины КД-2…4, три окна и 14 местных узлов.</td><td>Посадки брусьев, точное положение проходок, расхождения цепочек кровли.</td></tr>
 </tbody></table></div></div>
 <div class="issue-list">${DATA.issues.map(i=>`<article class="issue"><div class="issue-code">${i.id}</div><div><h3>${esc(i.title)}</h3><p>${esc(i.detail)}</p>${i.references.map(r=>sheetBtn(r.source_id,r.pdf_page,`${r.sheet||'Приложение'} · ${r.source_id} PDF ${r.pdf_page}`)).join('')}</div></article>`).join('')}</div>
 <div class="card"><h3>Проверки чисел</h3><p>14 совпадений и 6 расхождений исходных значений; дополнительно — независимая геометрическая сверка Фм 1. Несовпадения не исправлялись автоматически.</p><div class="table-wrap"><table><thead><tr><th>Проверка</th><th>Вычислено</th><th>Подпись</th><th>Разница</th><th>Результат</th></tr></thead><tbody>${DATA.checks.map(c=>`<tr><td>${esc(c.name)}</td><td class="number">${esc(c.calculated)} ${unit(c.unit)}</td><td class="number">${esc(c.printed)}</td><td class="number">${esc(c.difference)}</td><td class="${c.result==='match'?'check-good':'check-bad'}">${c.result==='match'?'совпадает':'расхождение'}</td></tr>`).join('')}</tbody></table></div></div>
 <div class="card"><h3>Вычисления этого просмотрщика</h3><div class="table-wrap"><table><thead><tr><th>Назначение</th><th>Формула</th><th>Результат</th><th>Ограничение</th></tr></thead><tbody>${MODEL.calculations.map(c=>`<tr><td>${esc(c.label)}</td><td class="number">${c.previous?`<del>${esc(c.previous.formula)}</del><br><strong class="updated">${esc(c.formula)}</strong>`:esc(c.formula)}</td><td class="number">${c.previous?`<del>${fmt(c.previous.value)}</del><br><strong class="updated">${fmt(c.value,8)}</strong>`:fmt(c.value,8)} ${unit(c.unit)}</td><td>${esc(c.note)}</td></tr>`).join('')}</tbody></table></div></div>
 <div class="card"><h3>Поиск по всем проверенным данным</h3><input type="search" id="fact-search" placeholder="Например: 1395, окно, плита, арматура…" aria-label="Поиск по базе фактов"><div class="fact-list" id="fact-search-results"></div></div>`;
 const search=()=>{const term=$('fact-search').value.trim().toLocaleLowerCase('ru');const hits=DATA.facts.filter(f=>!term||[f.label,f.id,f.value,f.note].join(' ').toLocaleLowerCase('ru').includes(term));$('fact-search-results').innerHTML=`<p class="tiny muted">Найдено ${hits.length}. Показано ${Math.min(hits.length,80)}.</p>`+hits.slice(0,80).map(f=>`<div class="fact-line"><div>${factBtn(f.id,f.label)}<small>${esc(f.source.sheet||'Приложение')} · PDF ${f.source.pdf_page} · ${f.verification==='visually_verified'?'сверено с листом':'расчёт'}${f.issue_id?' · '+f.issue_id:''}</small></div><strong>${esc(f.value)} ${unit(f.unit)}</strong></div>`).join('');};$('fact-search').oninput=search;search();
}

export { renderAuditPage };
